def insert_after_heading(doc: Document, heading: str, new_paragraphs: list[str]) -> None:
    for i, p in enumerate(doc.paragraphs):
        if p.text.strip() == heading:
            anchor = doc.paragraphs[i + 1] if i + 1 < len(doc.paragraphs) else p
            # Insert in order by placing last first before anchor.
            for text in reversed(new_paragraphs):
                anchor.insert_paragraph_before(text)
            return


def main() -> None:
    doc = Document(REPORT_PATH)
    for heading, paras in INSERTS.items():
        insert_after_heading(doc, heading, paras)
    doc.save(REPORT_PATH)
    words = sum(len(p.text.split()) for p in doc.paragraphs if p.text.strip())
    print("UPDATED", REPORT_PATH)
    print("WORD_COUNT", words)


if __name__ == "__main__":
    main()

